import { Axial, axialToOffset, hexDistance } from '../hex'
import { MapData, allHexes, terrainAt } from './terrain'
import type { Placement, UnitSheet } from './units'
import type { Troop } from './sheets'

/**
 * Deployment (guide, "Preparação rápida"): each player picks an edge of the map, the
 * other takes the opposite one, and every unit starts within 2 hexes of its own edge.
 */
export type Edge = 'west' | 'east' | 'north' | 'south'

export const EDGES: readonly Edge[] = ['west', 'east', 'north', 'south']

/** How many rows of hexes from the edge a troop may deploy on */
export const DEPLOY_DEPTH = 2

export function oppositeEdge(edge: Edge): Edge {
  switch (edge) {
  case 'west': return 'east'
  case 'east': return 'west'
  case 'north': return 'south'
  case 'south': return 'north'
  }
}

/** Rows of hexes between the hex and the edge: 1 = on the edge itself */
export function depthFromEdge(map: MapData, edge: Edge, hex: Axial): number {
  const { col, row } = axialToOffset(hex, map.orientation)
  switch (edge) {
  case 'west': return col + 1
  case 'east': return map.cols - col
  case 'north': return row + 1
  case 'south': return map.rows - row
  }
}

/** Position of the hex along the edge (row for the side edges, column for top and bottom) */
function alongEdge(map: MapData, edge: Edge, hex: Axial): number {
  const { col, row } = axialToOffset(hex, map.orientation)
  return edge === 'west' || edge === 'east' ? row : col
}

/** Within DEPLOY_DEPTH of the edge, on a hex a unit can stand on */
export function canDeployAt(map: MapData, edge: Edge, hex: Axial): boolean {
  const terrain = terrainAt(map, hex)
  return !!terrain && terrain.move !== 'blocked' && depthFromEdge(map, edge, hex) <= DEPLOY_DEPTH
}

/** Every hex a troop on this edge can deploy on */
export function deployZone(map: MapData, edge: Edge): Axial[] {
  return allHexes(map).filter(hex => canDeployAt(map, edge, hex))
}

export type DeployProblem = 'missing' | 'outside' | 'stacked'

/** What is wrong with a deployment (null: it is fine): every unit placed, inside the zone, one per hex */
export function deploymentProblem(map: MapData, edge: Edge, positions: (Axial | null)[], taken: Axial[] = []): DeployProblem | null {
  if (positions.some(pos => pos === null)) return 'missing'
  const placed = positions as Axial[]
  if (placed.some(pos => !canDeployAt(map, edge, pos))) return 'outside'
  const keys = [...placed, ...taken].map(pos => `${pos.q},${pos.r}`)
  if (new Set(keys).size !== keys.length) return 'stacked'
  return null
}

/** Shooters and casters stand behind the line (on the edge); the others in front */
const standsBehind = (sheet: UnitSheet) => !!sheet.ranged || sheet.spells.length > 0

/**
 * The standard formation (used by the CPU and as the starting layout for players):
 * the commander in the middle of the edge, fighters on the front row, shooters and
 * casters behind them, on open ground (no trees, sand, ruins) and, when there is room,
 * apart from each other so one area spell does not hit everybody.
 */
export function defaultDeployment(map: MapData, troop: Troop, edge: Edge, taken: Axial[] = []): Placement[] {
  const used = new Set(taken.map(hex => `${hex.q},${hex.r}`))
  const zone = deployZone(map, edge)
  const center = ((edge === 'west' || edge === 'east' ? map.rows : map.cols) - 1) / 2
  const order = troop.units
    .map((sheet, index) => ({ sheet, index }))
    .sort((a, b) => rank(a.sheet) - rank(b.sheet) || a.index - b.index)
  function rank(sheet: UnitSheet) {
    return sheet === troop.commander ? 0 : standsBehind(sheet) ? 2 : 1
  }

  const placed: Axial[] = []
  const result: Placement[] = new Array(troop.units.length)
  for (const { sheet, index } of order) {
    const row = standsBehind(sheet) ? 1 : DEPLOY_DEPTH
    let best: Axial | null = null
    let bestScore = Infinity
    for (const hex of zone) {
      if (used.has(`${hex.q},${hex.r}`)) continue
      const terrain = terrainAt(map, hex)!
      const along = alongEdge(map, edge, hex)
      let score = Math.abs(along - center)
      if (depthFromEdge(map, edge, hex) !== row) score += 3
      if (terrain.move !== 'easy') score += 20
      if (placed.some(other => hexDistance(other, hex) <= 1)) score += 4
      // ties: the lower half of the edge first, so the result never depends on the order of the zone
      score += (along > center ? 0 : 0.01)
      if (score < bestScore) {
        bestScore = score
        best = hex
      }
    }
    if (!best) throw new Error(`No room to deploy ${sheet.id} on the ${edge} edge`)
    used.add(`${best.q},${best.r}`)
    placed.push(best)
    result[index] = { sheet, pos: best, commander: sheet === troop.commander }
  }
  return result
}
