export type TroopId = 'human' | 'orc' | 'undead'

/** A suggested troop: who is in it and who commands it */
export interface Troop {
  id: TroopId
  name: string
  units: UnitSheet[]
  commander: UnitSheet
}

/** Carolina Ferrabrasa, 1 Mago, 1 Arqueiro e 3 Infantes: 440 points */
export const HUMAN_TROOP: Troop = {
  id: 'human',
  name: 'Humanos de Rubrágua',
  units: [CAROLINA, HUMAN_MAGE, HUMAN_ARCHER, HUMAN_INFANTRY, HUMAN_INFANTRY, HUMAN_INFANTRY],
  commander: CAROLINA
}

/** Retalhador como comandante, 1 Druida, 1 Arqueiro e 3 Infantes: 425 points */
