export const TROOP_IDS: readonly TroopId[] = ['human', 'orc', 'undead']

export const TROOPS: Record<TroopId, Troop> = { human: HUMAN_TROOP, orc: ORC_TROOP, undead: UNDEAD_TROOP }

export const troopPoints = (troop: Troop): number => troop.units.reduce((sum, sheet) => sum + sheet.points, 0)
