import type { TroopId } from '../rules/sheets'

/**
 * A side's color on the screen: `team` is the CSS class of the HUD and the menus (blue for
 * side A, red for side B, always); `hex` and `rgb` are the troop's own shade of it (rings, zones)
 */
export interface TeamColor { team: 'blue' | 'red', hex: string, rgb: string }

/**
 * Side A always plays in blue and side B always in red, whatever the troops (the same troop
 * on both sides included); each troop wears its own shade, so the troops still tell apart.
 * The minis are painted the same way (SHADES in scripts/minis/build-minis.ts).
 */
export const SIDE_COLORS: Record<TroopId, [TeamColor, TeamColor]> = {
  // royal blue / crimson
  human: [{ team: 'blue', hex: '#3d7bff', rgb: '61,123,255' }, { team: 'red', hex: '#ff4d4d', rgb: '255,77,77' }],
  // sky blue / vermilion
  orc: [{ team: 'blue', hex: '#3fb6ee', rgb: '63,182,238' }, { team: 'red', hex: '#ff7a3d', rgb: '255,122,61' }],
  // slate blue / wine
  undead: [{ team: 'blue', hex: '#8193c4', rgb: '129,147,196' }, { team: 'red', hex: '#d9487f', rgb: '217,72,127' }]
}

/** The color of a troop on a side of the match (0 = A, blue; 1 = B, red) */
export const sideColor = (troop: TroopId, side: 0 | 1): TeamColor => SIDE_COLORS[troop][side]

/** The commander of each troop, the face of the troop in the menus (unit sheet id) */
export const TROOP_FACE: Record<TroopId, string> = { human: 'carolina', orc: 'reaver', undead: 'berdolock' }
