/* eslint-disable no-console -- a script out of step with the rules is reported on the console for debugging */
import { TUTORIAL_STEPS, TutorialAction, TutorialDice, TutorialStep, sameAction } from './script'

export type BannerKind = 'turn' | 'morale'

/**
 * The tutorial during the match: where it is in TUTORIAL_STEPS, what the player may do now, and
 * the scripted enemy's next action. The match scene asks it before every player action
 * (`allows`), before every enemy action (`cpuAction`) and before every message in the middle of
 * the screen (`settle`, `openBanner`), and it moves on by itself. No engine and no UI here.
 *
 * Text steps wait for Next; a step of the player waits for exactly its action; an enemy step is
 * handed to the scene when the game waits for the enemy; a banner step shows while its banner is
 * open and goes on with the banner's Continue.
 *
 * If the script ever disagrees with the game (a bug: tests/tutorial.test.ts guards it), the
 * tutorial gives up (`broken`): the player plays freely, the AI takes over and the dice are real.
 */
export class TutorialRun {
  readonly dice = new TutorialDice()
  index = 0
  broken = false
  /** Bumped every time the player tries something else: the panel shakes */
  refusals = 0
  /** The banner on screen, if any */
  private banner: BannerKind | null = null
  private waiters: (() => void)[] = []

  constructor(private readonly changed: () => void = () => {}) {}

  get step(): TutorialStep | undefined {
    return this.broken ? undefined : TUTORIAL_STEPS[this.index]
  }

  get progress(): number {
    return Math.min(1, this.index / TUTORIAL_STEPS.length)
  }

  /** The step whose text belongs on the panel now (a banner step only while its banner is open) */
  shownStep(): TutorialStep | undefined {
    const step = this.step
    if (step?.kind === 'banner') return this.banner === step.on ? step : undefined
    return step
  }

  /** A text step is waiting for Next */
  get waitingNext(): boolean {
    return this.step?.kind === 'info'
  }

  next() {
    if (this.waitingNext) this.advance()
  }

  /** The player's action the tutorial waits for */
  expected(): TutorialAction | null {
    const step = this.step
    return step?.kind === 'do' ? step.action : null
  }

  /** May the player do this now? (anything, once the tutorial gave up) */
  allows(action: TutorialAction): boolean {
    if (this.broken) return true
    const expected = this.expected()
    return !!expected && sameAction(expected, action)
  }

  /** May the player select this unit now? */
  allowsUnit(unitId: number): boolean {
    if (this.broken) return true
    const expected = this.expected()
    return !!expected && expected.a !== 'first' && expected.unit === unitId
  }

  /** The player's allowed action is about to be applied: load its dice */
  begin() {
    const step = this.step
    if (step?.kind === 'do') this.dice.load(step.dice)
  }

  /** The player's action went through */
  done() {
    if (this.step?.kind !== 'do') return
    this.checkDice(this.index)
    this.advance()
  }

  refuse() {
    this.refusals++
    this.changed()
  }

  /**
   * The enemy's next action, once the text steps before it were read. Null when the script is out
   * of step (the scene then lets the AI play).
   */
  async cpuAction(): Promise<TutorialAction | null> {
    await this.settle()
    const step = this.step
    if (!step) return null
    if (step.kind !== 'cpu') {
      this.fail(`the enemy has to act, but step ${this.index} is "${step.kind}"`)
      return null
    }
    this.dice.load(step.dice)
    this.advance()
    return step.action
  }

  /** Called after the enemy's action was applied: its dice must all have been rolled */
  cpuDone() {
    this.checkDice(this.index - 1)
  }

  /** Waits until no text step is waiting for Next (before the enemy acts or a banner opens) */
  async settle() {
    while (this.step?.kind === 'info') await new Promise<void>(resolve => this.waiters.push(resolve))
  }

  openBanner(kind: BannerKind) {
    this.banner = kind
    this.changed()
  }

  /** The banner's Continue: a banner step for it goes on */
  closeBanner(kind: BannerKind) {
    this.banner = null
    const step = this.step
    if (step?.kind === 'banner' && step.on === kind) this.advance()
    else this.changed()
  }

  /** Every step was played */
  get finished(): boolean {
    return this.index >= TUTORIAL_STEPS.length
  }

  /** Stops waiting (the match is leaving) */
  dispose() {
    this.broken = true
    this.wake()
  }

  private checkDice(step: number) {
    if (this.dice.left > 0 || this.dice.extra > 0) {
      this.fail(`step ${step} rolled ${this.dice.extra} dice too many and left ${this.dice.left}`)
    }
  }

  /** The script and the game disagree: the tutorial stops guiding (the match goes on freely) */
  fail(why: string) {
    if (this.broken) return
    console.error(`Tutorial out of step with the game: ${why}`)
    this.broken = true
    this.wake()
    this.changed()
  }

  private advance() {
    this.index++
    this.wake()
    this.changed()
  }

  private wake() {
    const waiters = this.waiters
    this.waiters = []
    waiters.forEach(resolve => resolve())
  }
}

const PREF_DONE = 'onagro.tutorial.done'

export function isTutorialDone(): boolean {
  try { return localStorage.getItem(PREF_DONE) === '1' } catch { return false }
}

export function markTutorialDone() {
  try { localStorage.setItem(PREF_DONE, '1') } catch { /* storage unavailable */ }
}
