import * as ex from 'excalibur'
import { MINIS, PORTRAITS, Resources } from './resources'
import LoaderLogoPath from './assets/loader-logo.png'

/** Space between the logo and the loading bar (CSS px) */
const LOGO_GAP = 48
/** Height of Excalibur's loading bar */
const BAR_HEIGHT = 20
/**
 * The logo shows with the bar still empty this long before the loading starts (real time: it is
 * there to be seen); the bar then fills and the title screen comes right after, with no stop at
 * the full bar that would feel like a freeze
 */
const BEFORE_LOAD_PAUSE = 1000

/**
 * Loading screen: the logo with the bar below it, the two centered on the screen as one block
 * (Excalibur's default puts the logo above the middle and the bar on it). Shows the logo a moment,
 * loads every asset in Resources, then goes straight to the title screen. No PLAY!
 * button: the sound comes on with the first click, tap or key on the page (sound-unlock.ts)
 */
class OnagroLoader extends ex.Loader {
  override onDraw(ctx: CanvasRenderingContext2D) {
    // the same sizes Excalibur's onDraw uses
    const engine = this.engine
    if (engine) {
      const width = engine.canvasWidth / engine.pixelRatio
      const height = engine.canvasHeight / engine.pixelRatio
      const logoWidth = Math.min(this.logoWidth, width * 0.75)
      const logoHeight = Math.floor(logoWidth * (this.logoHeight / this.logoWidth))
      const x = width / 2 - logoWidth / 2
      const top = Math.round((height - (logoHeight + LOGO_GAP + BAR_HEIGHT)) / 2)
      this.logoPosition = ex.vec(x, top)
      this.loadingBarPosition = ex.vec(x, top + logoHeight + LOGO_GAP)
    }
    super.onDraw(ctx)
  }

  override async load() {
    await new Promise(resolve => window.setTimeout(resolve, BEFORE_LOAD_PAUSE))
    return super.load()
  }
}

export const loader = new OnagroLoader()
loader.backgroundColor = 'black'
loader.suppressPlayButton = true

// the Voxelhouse logo (yarn logo), the same as on the title screen, 800x312.
// Drawn in canvas resolution units, so it scales with the screen like the game.
loader.logo = LoaderLogoPath
loader.logoWidth = 800
loader.logoHeight = 312

for (const res of [...Object.values(Resources), ...Object.values(MINIS), ...Object.values(PORTRAITS)]) {
  loader.addResource(res)
}
